insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-indigenous-societies', 'ch-theme-1', 'Indigenous societies before 1492', 'The Caribbean was already home to diverse societies before Europeans arrived. Think of the sea as a route for travel, exchange and kinship as well as a boundary.', 0, true, '{"syllabus":{"theme":1,"revisedTheme":1,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"The Caribbean was already home to diverse societies before Europeans arrived. Think of the sea as a route for travel, exchange and kinship as well as a boundary.","objectives":["How does a surviving zemí broaden the evidence about Taíno life?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Taíno communities in the Greater Antilles cultivated cassava, maize and other crops. They fished, traded and made pottery. A cacique led a community or a group of settlements. Zemí traditions connected spiritual forces and ancestors to everyday life and political authority.","Kalinago communities in the Lesser Antilles used skilled canoe travel for trade, diplomacy and warfare. The Maya in mainland Mesoamerica developed cities, writing, calendars and intensive agriculture. Comparing these societies by location, leadership and food production is more useful than ranking them as simple or advanced."]},{"title":"Work through an example","paragraphs":["Compare a Taíno farming settlement and a Maya city. Both depended on agriculture, but the city had monumental centres and a different scale of administration."]}],"summary":"It gives material evidence of artistic skill, ceremonial life and beliefs that can be considered alongside European accounts.","check":{"question":"How does a surviving zemí broaden the evidence about Taíno life?","answer":"It gives material evidence of artistic skill, ceremonial life and beliefs that can be considered alongside European accounts."},"flashcards":[{"id":"ch-indigenous-societies-check","front":"How does a surviving zemí broaden the evidence about Taíno life?","back":"It gives material evidence of artistic skill, ceremonial life and beliefs that can be considered alongside European accounts."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-migration-and-settlement', 'ch-theme-1', 'How the islands were settled', 'Peoples reached and settled the Caribbean in several movements over thousands of years. Archaeology helps trace them through objects, food remains and settlements.', 1, true, '{"syllabus":{"theme":1,"revisedTheme":1,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Peoples reached and settled the Caribbean in several movements over thousands of years. Archaeology helps trace them through objects, food remains and settlements.","objectives":["Why do historians combine pottery, language and settlement evidence?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Communities moved from parts of mainland Central or South America at different times. Later ceramic-making communities travelled from northern South America through the Lesser Antilles and into the Greater Antilles. Pottery styles and related languages are clues. They do not establish one exact route or a single migration date.","Coastal sites offered fish, shellfish and access to other islands. Inland land, soil and water supported agriculture and larger settlements. In the Maya region, reservoirs and other ways of managing seasonal water made settlement possible where surface water was scarce. Maya cities also used architecture, astronomy and calendars in political and ceremonial life."]},{"title":"Work through an example","paragraphs":["If similar pottery appears on two islands, propose travel or exchange as a possible explanation. Check dates and other artefacts before claiming that a whole community migrated."]}],"summary":"The sources answer different questions. Together they help distinguish settlement, contact and exchange.","check":{"question":"Why do historians combine pottery, language and settlement evidence?","answer":"The sources answer different questions. Together they help distinguish settlement, contact and exchange."},"flashcards":[{"id":"ch-migration-and-settlement-check","front":"Why do historians combine pottery, language and settlement evidence?","back":"The sources answer different questions. Together they help distinguish settlement, contact and exchange."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-encounter-and-conquest', 'ch-theme-1', 'European arrival, conquest and exchange', 'In 1492 Columbus reached the Caribbean while seeking a western route to Asia. Spanish settlement soon turned contact into a struggle over land and labour.', 2, true, '{"syllabus":{"theme":1,"revisedTheme":1,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"In 1492 Columbus reached the Caribbean while seeking a western route to Asia. Spanish settlement soon turned contact into a struggle over land and labour.","objectives":["Why is disease alone an incomplete explanation?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Spanish expansion combined wealth, imperial rivalry and religious conversion. In Hispaniola settlers sought gold and food. Under the encomienda, settlers were granted claims to Indigenous tribute or labour, with nominal duties of protection and Christian instruction. In practice, forced work and punishment could be severe.","Disease, violence, overwork, displacement and disruption of food production contributed to population decline. Cassava and maize spread beyond the Americas while horses, cattle and sugar cane moved into the Americas. Indigenous peoples survived and their descendants, knowledge and language remain part of the region."]},{"title":"Work through an example","paragraphs":["In an explanation of population decline, link forced labour to lost farming time and hunger, then show how hunger increased vulnerability to illness."]}],"summary":"Disease interacted with conquest, displacement, forced labour and hunger. The relative weight of these factors varied by place and time.","check":{"question":"Why is disease alone an incomplete explanation?","answer":"Disease interacted with conquest, displacement, forced labour and hunger. The relative weight of these factors varied by place and time."},"flashcards":[{"id":"ch-encounter-and-conquest-check","front":"Why is disease alone an incomplete explanation?","back":"Disease interacted with conquest, displacement, forced labour and hunger. The relative weight of these factors varied by place and time."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-indigenous-resistance', 'ch-theme-1', 'Indigenous resistance and survival', 'Indigenous responses included armed resistance, diplomacy, migration and rebuilding communities.', 3, true, '{"syllabus":{"theme":1,"revisedTheme":2,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Indigenous responses included armed resistance, diplomacy, migration and rebuilding communities.","objectives":["What is one way to resist colonisation without a battle?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Taíno communities resisted Spanish demands for tribute and work. Enriquillo used mountain terrain in Hispaniola and eventually negotiated an agreement in 1533. Hatuey moved from Hispaniola to Cuba and organised resistance to Spanish conquest there.","Kalinago groups defended settlements and used mobility, raids and alliances to resist European encroachment in the Lesser Antilles. Resistance could protect autonomy for a time even when European colonisation continued. Read colonial descriptions critically because writers had reasons to portray resistance as a threat."]},{"title":"Work through an example","paragraphs":["Compare Enriquillo’s negotiated settlement with a Kalinago strategy of mobility. Each used geography and local knowledge, with different political outcomes."]}],"summary":"A community might relocate to defend its autonomy, negotiate an agreement, or protect practices and knowledge across generations.","check":{"question":"What is one way to resist colonisation without a battle?","answer":"A community might relocate to defend its autonomy, negotiate an agreement, or protect practices and knowledge across generations."},"flashcards":[{"id":"ch-indigenous-resistance-check","front":"What is one way to resist colonisation without a battle?","back":"A community might relocate to defend its autonomy, negotiate an agreement, or protect practices and knowledge across generations."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-sugar-transition', 'ch-theme-2', 'From tobacco to sugar', 'In the seventeenth century, sugar transformed colonies such as Barbados because it offered high returns to investors who could afford land, equipment and labour.', 4, true, '{"syllabus":{"theme":2,"revisedTheme":1,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"In the seventeenth century, sugar transformed colonies such as Barbados because it offered high returns to investors who could afford land, equipment and labour.","objectives":["Why did sugar encourage larger estates?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Earlier English settlements grew crops such as tobacco and cotton. Competition from North American tobacco producers reduced the attraction of tobacco. European demand for sugar and access to credit, shipping and milling knowledge encouraged the switch.","Cane had to be processed quickly after cutting. Mills, boiling houses and large gangs made sugar expensive to establish. Wealthier planters bought or consolidated land. The demand for labour expanded the forced movement and chattel enslavement of Africans, reshaping population, law and political power."]},{"title":"Work through an example","paragraphs":["Explain the change with a chain: access to credit paid for mills, mills made large-scale processing possible, and scale favoured large estates."]}],"summary":"The costs of mills and boiling houses and the demand for coordinated labour favoured growers able to finance large operations.","check":{"question":"Why did sugar encourage larger estates?","answer":"The costs of mills and boiling houses and the demand for coordinated labour favoured growers able to finance large operations."},"flashcards":[{"id":"ch-sugar-transition-check","front":"Why did sugar encourage larger estates?","back":"The costs of mills and boiling houses and the demand for coordinated labour favoured growers able to finance large operations."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-atlantic-trade', 'ch-theme-2', 'The Atlantic trade in enslaved people', 'The Middle Passage was the forced Atlantic crossing of captive Africans. It was one stage in a wider trade driven by plantation demand.', 5, true, '{"syllabus":{"theme":2,"revisedTheme":1,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"The Middle Passage was the forced Atlantic crossing of captive Africans. It was one stage in a wider trade driven by plantation demand.","objectives":["What is the difference between the Middle Passage and the triangular trade?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Captives were taken through warfare, raids, kidnapping and other routes into captivity. Traders held and sold captives on the African coast. Shipboard crowding, disease and violence caused suffering and deaths. Survivors faced sale, separation and forced labour in the Americas.","A triangular route can show some connections among Europe, Africa and the Americas: merchandise, captive people, and plantation exports moved across the Atlantic. Actual voyages did not all make the same three stops. Treat the triangle as a model and people’s accounts as evidence of what the system meant for those forced through it."]},{"title":"Work through an example","paragraphs":["A shipping record can show departures, arrivals and losses, while a first-person account can show conditions and resistance that a table cannot describe."]}],"summary":"The Middle Passage refers to the forced crossing to the Americas. The triangle represents several connected commercial routes.","check":{"question":"What is the difference between the Middle Passage and the triangular trade?","answer":"The Middle Passage refers to the forced crossing to the Americas. The triangle represents several connected commercial routes."},"flashcards":[{"id":"ch-atlantic-trade-check","front":"What is the difference between the Middle Passage and the triangular trade?","back":"The Middle Passage refers to the forced crossing to the Americas. The triangle represents several connected commercial routes."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-plantation-labour', 'ch-theme-2', 'How a plantation worked', 'A sugar estate was both a farm and a factory. Its timetable depended on getting freshly cut cane to the mill before the juice deteriorated.', 6, true, '{"syllabus":{"theme":2,"revisedTheme":1,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"A sugar estate was both a farm and a factory. Its timetable depended on getting freshly cut cane to the mill before the juice deteriorated.","objectives":["What connects field labour to the boiling house?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Field gangs planted, weeded and cut cane. Cane moved to rollers, which crushed it. Workers clarified and boiled the juice, then crystallised and cured the sugar. Molasses could be distilled into rum. Skilled workers such as coopers, carpenters and boilers were essential.","Estate organisation rested on compulsion. Owners and managers set labour demands. Overseers and drivers enforced them. Domestic, artisan and field labour differed in task and location, but legal ownership and coercion shaped each experience. Provision grounds and markets also allowed some families to grow food and trade."]},{"title":"Work through an example","paragraphs":["Use the mill as evidence of labour organisation. It required field transport, machine operation and skilled boiling to be coordinated in one production cycle."]}],"summary":"Cut cane had to reach the mill promptly. The extracted juice then went to the boiling house, tying each stage to the one before it.","check":{"question":"What connects field labour to the boiling house?","answer":"Cut cane had to reach the mill promptly. The extracted juice then went to the boiling house, tying each stage to the one before it."},"flashcards":[{"id":"ch-plantation-labour-check","front":"What connects field labour to the boiling house?","back":"Cut cane had to reach the mill promptly. The extracted juice then went to the boiling house, tying each stage to the one before it."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-slavery-and-legacy', 'ch-theme-2', 'Chattel slavery, control and cultural legacies', 'In Caribbean plantation slavery, people could be bought, sold and inherited. Colonial law generally made an enslaved woman’s children enslaved.', 7, true, '{"syllabus":{"theme":2,"revisedTheme":1,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"In Caribbean plantation slavery, people could be bought, sold and inherited. Colonial law generally made an enslaved woman’s children enslaved.","objectives":["How can a system end in law while its effects continue?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Slave codes restricted movement, meetings, legal rights and freedom. Planters used punishment, surveillance and division by occupation or status. Defenders invoked racist ideas, property and religion to justify an economic system from which they benefited.","Systems of captivity and dependency varied across Africa. In some societies captives could enter a household or gain freedom, while other forms involved sale, inherited status or harsh exploitation. Compare rights and conditions in named settings instead of generalising about an entire continent.","Families and communities preserved and transformed languages, foodways, religious practices and music under extreme pressure. Colonial patterns of land ownership, racial hierarchy and unequal access to capital continued to influence opportunities after legal emancipation."]},{"title":"Work through an example","paragraphs":["A local market illustrates continuity and change. Families drew on knowledge and networks built under slavery and used them to seek income and autonomy after emancipation."]}],"summary":"Legal freedom did not automatically redistribute land, wealth or political power. Those inequalities continued to affect employment and opportunity.","check":{"question":"How can a system end in law while its effects continue?","answer":"Legal freedom did not automatically redistribute land, wealth or political power. Those inequalities continued to affect employment and opportunity."},"flashcards":[{"id":"ch-slavery-and-legacy-check","front":"How can a system end in law while its effects continue?","back":"Legal freedom did not automatically redistribute land, wealth or political power. Those inequalities continued to affect employment and opportunity."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-timber-and-trade', 'ch-theme-2', 'Timber, other crops and colonial markets', 'Sugar dominated much of the Caribbean, while other colonies organised labour around forest products or crops such as coffee, cocoa and cotton.', 8, true, '{"syllabus":{"theme":2,"revisedTheme":1,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Sugar dominated much of the Caribbean, while other colonies organised labour around forest products or crops such as coffee, cocoa and cotton.","objectives":["Why was mahogany transport a major part of production?"],"sections":[{"title":"What happened and why it matters","paragraphs":["In the Bay of Honduras, logwood supplied dyes for European textile makers. Mahogany grew in importance with demand for durable furniture wood. Cutting mahogany required locating scattered trees, felling and trimming them, and moving heavy logs to waterways. Timber work could involve small dispersed gangs and greater mobility than tightly supervised sugar fields, while both relied on coerced labour.","Exporters depended on buyers, shipping and merchant credit. Caribbean sugar went especially to European markets. Molasses fed rum production through fermentation and distillation, and merchants sold rum within the Atlantic economy. Storms, war, falling prices and expensive credit could undermine profits."]},{"title":"Work through an example","paragraphs":["Compare supervision by considering where work happened. A timber cutter might work far inland with a small group. A cane gang worked closer to an estate’s mill and supervisors."]}],"summary":"Trees were dispersed, the timber was heavy, and logs had to be moved from the forest to rivers or coastal export points.","check":{"question":"Why was mahogany transport a major part of production?","answer":"Trees were dispersed, the timber was heavy, and logs had to be moved from the forest to rivers or coastal export points."},"flashcards":[{"id":"ch-timber-and-trade-check","front":"Why was mahogany transport a major part of production?","back":"Trees were dispersed, the timber was heavy, and logs had to be moved from the forest to rivers or coastal export points."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-everyday-resistance', 'ch-theme-3', 'Everyday resistance and Maroon communities', 'Enslaved people resisted through everyday actions, cultural survival, flight and organised revolt.', 9, true, '{"syllabus":{"theme":3,"revisedTheme":2,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Enslaved people resisted through everyday actions, cultural survival, flight and organised revolt.","objectives":["Why did terrain matter to Maroon resistance?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Work slowdowns, breaking tools, bargaining, learning in secret and protecting kin could reduce planter control or preserve autonomy. Running away for a short period could support negotiation or family visits. Permanent flight sometimes led to independent Maroon communities.","Jamaican Maroons used mountains, forests, local knowledge and military tactics to defend communities. Treaties in 1739 and 1740 recognised some autonomy but imposed obligations, including returning later fugitives. Suriname also developed enduring Maroon societies in its forested interior."]},{"title":"Work through an example","paragraphs":["A treaty can be both a victory for a community and a compromise that limits its future choices. Explain both effects."]}],"summary":"Defenders used difficult terrain and local knowledge for concealment, communication and ambush, increasing the cost of colonial campaigns.","check":{"question":"Why did terrain matter to Maroon resistance?","answer":"Defenders used difficult terrain and local knowledge for concealment, communication and ambush, increasing the cost of colonial campaigns."},"flashcards":[{"id":"ch-everyday-resistance-check","front":"Why did terrain matter to Maroon resistance?","back":"Defenders used difficult terrain and local knowledge for concealment, communication and ambush, increasing the cost of colonial campaigns."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-rebellions', 'ch-theme-3', 'Compare Caribbean rebellions', 'A revolt can fail militarily and still change the politics of slavery. Compare aims, organisation, repression and longer-term consequences.', 10, true, '{"syllabus":{"theme":3,"revisedTheme":2,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"A revolt can fail militarily and still change the politics of slavery. Compare aims, organisation, repression and longer-term consequences.","objectives":["How could a defeated revolt still advance abolition?"],"sections":[{"title":"What happened and why it matters","paragraphs":["The Berbice uprising began in 1763 in a Dutch colony. Coffij helped lead rebels who controlled much of the colony for a time. Internal divisions and outside military aid to the Dutch helped the authorities regain control.","Bussa’s Rebellion in Barbados in 1816, the Demerara uprising in 1823 and the Baptist War in Jamaica in 1831–32 exposed the scale of opposition to enslavement. Rumours about freedom, missionary networks, expectations of reform and harsh conditions mattered differently in each colony.","The Baptist War grew out of a planned withdrawal of labour and escalated into armed conflict and fires. The colonial response was brutal. Reports of revolt and repression gave British abolitionists further evidence against the system."]},{"title":"Work through an example","paragraphs":["Compare Demerara with Jamaica: connect named leaders or networks to how people coordinated, then distinguish immediate repression from effects on abolition debate."]}],"summary":"It showed the instability and violence of slavery and gave campaigners evidence with which to challenge planters and pressure Parliament.","check":{"question":"How could a defeated revolt still advance abolition?","answer":"It showed the instability and violence of slavery and gave campaigners evidence with which to challenge planters and pressure Parliament."},"flashcards":[{"id":"ch-rebellions-check","front":"How could a defeated revolt still advance abolition?","back":"It showed the instability and violence of slavery and gave campaigners evidence with which to challenge planters and pressure Parliament."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-haitian-revolution', 'ch-theme-3', 'The Haitian Revolution, 1791–1804', 'In Saint-Domingue, enslaved people turned an uprising into a revolution that ended French colonial rule and created independent Haiti.', 11, true, '{"syllabus":{"theme":3,"revisedTheme":2,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"In Saint-Domingue, enslaved people turned an uprising into a revolution that ended French colonial rule and created independent Haiti.","objectives":["Why are 1791, 1794 and 1804 all important?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Saint-Domingue was a rich plantation colony with a large enslaved majority. Wealthy white planters, poorer whites and free people of colour had competing demands. The French Revolution opened arguments over citizenship and rights while plantations remained violent.","The uprising began in 1791. France abolished slavery in its colonies in 1794. Toussaint Louverture emerged as a key military and political leader. Napoleon sent an expedition in 1802, Louverture was captured, and forces led by Jean-Jacques Dessalines and others defeated the French. Haiti declared independence in 1804.","Organised resistance, French military losses and disease all mattered. Independence inspired some and alarmed slaveholders elsewhere. France’s defeat also helped clear the way for the Louisiana Purchase in 1803, while Haiti faced diplomatic isolation and later a French indemnity."]},{"title":"Work through an example","paragraphs":["To explain victory, connect local military organisation and French losses. Simply saying that disease defeated France leaves out the choices and actions of revolutionaries."]}],"summary":"They mark the uprising, French abolition during the revolution, and Haitian independence respectively.","check":{"question":"Why are 1791, 1794 and 1804 all important?","answer":"They mark the uprising, French abolition during the revolution, and Haitian independence respectively."},"flashcards":[{"id":"ch-haitian-revolution-check","front":"Why are 1791, 1794 and 1804 all important?","back":"They mark the uprising, French abolition during the revolution, and Haitian independence respectively."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-abolition-campaigns', 'ch-theme-4', 'Abolition campaigns in Britain and France', 'The legal end of the slave trade and the legal end of slavery were separate changes.', 12, true, '{"syllabus":{"theme":4,"revisedTheme":3,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"The legal end of the slave trade and the legal end of slavery were separate changes.","objectives":["What changed in British law in 1807?"],"sections":[{"title":"What happened and why it matters","paragraphs":["In Britain, Black abolitionists such as Olaudah Equiano, formerly enslaved witnesses, religious groups and parliamentary campaigners used testimony, petitions, publications and boycotts. Planters and merchants defended property and trade. The British slave trade was outlawed in 1807, while the Slavery Abolition Act was passed in 1833.","Resistance in the colonies and political and economic debates in Britain affected the timing. Changes in trade or profitability alone cannot explain why Parliament acted when it did. In France, revolutionary abolition in 1794 was followed by restoration under Napoleon in parts of the empire in 1802. France abolished slavery definitively in 1848."]},{"title":"Work through an example","paragraphs":["A strong answer can put an abolitionist petition next to evidence from a revolt and explain how public pressure and the costs of repression reinforced one another."]}],"summary":"Britain banned its slave trade. The law did not free people already held in slavery in British colonies.","check":{"question":"What changed in British law in 1807?","answer":"Britain banned its slave trade. The law did not free people already held in slavery in British colonies."},"flashcards":[{"id":"ch-abolition-campaigns-check","front":"What changed in British law in 1807?","back":"Britain banned its slave trade. The law did not free people already held in slavery in British colonies."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-apprenticeship', 'ch-theme-4', 'Emancipation and apprenticeship', 'British emancipation in 1834 opened a transition. In many colonies, formerly enslaved adults still owed labour under apprenticeship until 1838.', 13, true, '{"syllabus":{"theme":4,"revisedTheme":3,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"British emancipation in 1834 opened a transition. In many colonies, formerly enslaved adults still owed labour under apprenticeship until 1838.","objectives":["Why is 1838 used alongside 1834?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Owners received compensation. Apprentices received limited time for their own earnings but were required to perform unpaid labour for former owners. Stipendiary magistrates were intended to regulate disputes. Coercion and abuse persisted. Antigua did not adopt apprenticeship and moved to immediate emancipation in 1834.","In 1838 apprenticeship ended early across the colonies that still used it. Former apprentices had greater legal freedom to choose work and where to live, while land prices, wages, discrimination and labour rules continued to shape those choices. French emancipation in 1848 followed a separate legal and political path."]},{"title":"Work through an example","paragraphs":["Compare a former apprentice’s legal rights in 1834 and 1838. Then ask whether that person had practical access to housing or independent land."]}],"summary":"1834 marks the start of legal emancipation and apprenticeship in much of the British Caribbean. In 1838 the remaining apprentices were released from compulsory labour.","check":{"question":"Why is 1838 used alongside 1834?","answer":"1834 marks the start of legal emancipation and apprenticeship in much of the British Caribbean. In 1838 the remaining apprentices were released from compulsory labour."},"flashcards":[{"id":"ch-apprenticeship-check","front":"Why is 1838 used alongside 1834?","back":"1834 marks the start of legal emancipation and apprenticeship in much of the British Caribbean. In 1838 the remaining apprentices were released from compulsory labour."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-amelioration', 'ch-theme-4', 'Amelioration and the limits of reform', 'Amelioration meant improving some conditions under slavery while keeping the system in place.', 14, true, '{"syllabus":{"theme":4,"revisedTheme":3,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Amelioration meant improving some conditions under slavery while keeping the system in place.","objectives":["Why did amelioration fall short of emancipation?"],"sections":[{"title":"What happened and why it matters","paragraphs":["In the British Caribbean, reform proposals in the 1820s included measures concerning family life, religious instruction, punishment and evidence in court. Colonial assemblies and planters resisted or diluted some changes, and enforcement differed by colony. France also adopted measures regulating conditions before emancipation in 1848.","Spanish abolition followed a later course in its remaining Caribbean colonies. Puerto Rico abolished slavery in 1873 and Cuba in 1886. Reform, war, resistance and the needs of slaveholding economies shaped the pace differently in each empire."]},{"title":"Work through an example","paragraphs":["Compare the rule on paper with evidence of enforcement. A restriction on punishment offers limited protection if an enslaved person cannot report a violation safely."]}],"summary":"It changed some rules about treatment while keeping legal ownership and compulsory labour in place.","check":{"question":"Why did amelioration fall short of emancipation?","answer":"It changed some rules about treatment while keeping legal ownership and compulsory labour in place."},"flashcards":[{"id":"ch-amelioration-check","front":"Why did amelioration fall short of emancipation?","back":"It changed some rules about treatment while keeping legal ownership and compulsory labour in place."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-free-villages', 'ch-theme-5', 'Free villages and the peasantry', 'Many freed people sought control over work, family life and time by buying or renting land and selling produce.', 15, true, '{"syllabus":{"theme":5,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Many freed people sought control over work, family life and time by buying or renting land and selling produce.","objectives":["Why did free villages matter beyond farming?"],"sections":[{"title":"What happened and why it matters","paragraphs":["A peasant farmer typically worked a small holding. Families combined food production, sales and wage work. In Jamaica, missionaries sometimes helped organise land purchases for free villages. In British Guiana, groups of freed people pooled resources to buy estates, including Plantation Northbrook, renamed Victoria.","Access to land differed. Barbados had dense population and little unoccupied cultivable land. In Jamaica and Trinidad some households had more opportunity to settle outside estates. Planters could use rents, land policy or wage arrangements to pressure workers to remain."]},{"title":"Work through an example","paragraphs":["Compare Jamaica with Barbados using land access as the factor, then explain how land availability changed the ability to refuse low wages."]}],"summary":"They gave residents greater independence and places to build schools, churches, family networks and local markets.","check":{"question":"Why did free villages matter beyond farming?","answer":"They gave residents greater independence and places to build schools, churches, family networks and local markets."},"flashcards":[{"id":"ch-free-villages-check","front":"Why did free villages matter beyond farming?","back":"They gave residents greater independence and places to build schools, churches, family networks and local markets."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-indenture', 'ch-theme-5', 'Indentured labour and new communities', 'Planters recruited workers under contracts after emancipation to secure labour and restrain wage costs.', 16, true, '{"syllabus":{"theme":5,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Planters recruited workers under contracts after emancipation to secure labour and restrain wage costs.","objectives":["Why did planters favour indenture?"],"sections":[{"title":"What happened and why it matters","paragraphs":["British Guiana received Indian indentured labourers from 1838 and Trinidad from 1845. Chinese, Portuguese Madeiran, African and other migrants also came under different arrangements. Routes, occupations and numbers differed across colonies.","Indenture involved a contract, a term of service and payment. Employers and colonial officials used penal sanctions and restrictions on movement, and recruiters could misrepresent conditions. Contract labour differed legally from chattel slavery, while both systems could limit workers’ freedom severely.","Many migrants stayed after their contracts and built family, religious, agricultural and commercial institutions. Food, festivals and places of worship show long-term cultural change, alongside conflict and unequal access to power."]},{"title":"Work through an example","paragraphs":["In a comparison, discuss recruitment, pay, duration, legal status and how each system was enforced. Include what workers actually experienced."]}],"summary":"It gave estates a more predictable labour supply and reduced their dependence on bargaining with workers who could leave for other employment.","check":{"question":"Why did planters favour indenture?","answer":"It gave estates a more predictable labour supply and reduced their dependence on bargaining with workers who could leave for other employment."},"flashcards":[{"id":"ch-indenture-check","front":"Why did planters favour indenture?","back":"It gave estates a more predictable labour supply and reduced their dependence on bargaining with workers who could leave for other employment."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-crown-colony', 'ch-theme-5', 'Crown Colony government after emancipation', 'Before Crown Colony government, elected assemblies could represent a narrow group of property owners while excluding most of the population.', 17, true, '{"syllabus":{"theme":5,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Before Crown Colony government, elected assemblies could represent a narrow group of property owners while excluding most of the population.","objectives":["What changed when Jamaica became a Crown Colony?"],"sections":[{"title":"What happened and why it matters","paragraphs":["In Jamaica, the Morant Bay uprising in 1865 exposed grievances over land, poverty, taxation, and access to justice. Governor Edward Eyre’s violent repression drew controversy. Jamaica’s assembly surrendered its old constitution and Crown Colony government concentrated authority in the governor and appointed officials.","The Colonial Office sought more direct control and fewer conflicts with locally entrenched assemblies. Direct rule could override planter interests while giving most people little formal influence. Evaluate the change by asking which authorities gained power and whether ordinary people gained votes."]},{"title":"Work through an example","paragraphs":["Compare who could influence an elected planter-dominated assembly and who could influence an appointed council. Both arrangements restricted participation, for different reasons."]}],"summary":"Authority shifted away from the old representative assembly towards the governor and officials responsible to Britain.","check":{"question":"What changed when Jamaica became a Crown Colony?","answer":"Authority shifted away from the old representative assembly towards the governor and officials responsible to Britain."},"flashcards":[{"id":"ch-crown-colony-check","front":"What changed when Jamaica became a Crown Colony?","back":"Authority shifted away from the old representative assembly towards the governor and officials responsible to Britain."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-sugar-competition', 'ch-theme-6', 'Sugar, competition and new crops', 'After emancipation, Caribbean producers faced changes in market access, rising competition and pressure to modernise.', 18, true, '{"syllabus":{"theme":6,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"After emancipation, Caribbean producers faced changes in market access, rising competition and pressure to modernise.","objectives":["How did central factories change sugar production?"],"sections":[{"title":"What happened and why it matters","paragraphs":["The Sugar Duties Act of 1846 began reducing British preferential protection for colonial sugar. European beet sugar and large producers elsewhere added competition. Estates responded by consolidating, investing in central factories or abandoning production where costs were too high.","Diversification meant developing other crops and earnings. Examples include bananas in Jamaica and later the Windward Islands, cocoa in Trinidad and rice in British Guiana. New crops could widen opportunities and still expose producers to price swings, shipping costs or market dependence."]},{"title":"Work through an example","paragraphs":["Explain a decline using two connected pressures: lower prices reduced revenue while costly mills and transport made it hard to cut unit costs."]}],"summary":"A larger factory could process cane from several farms or estates, spreading the cost of machinery across more output.","check":{"question":"How did central factories change sugar production?","answer":"A larger factory could process cane from several farms or estates, spreading the cost of machinery across more output."},"flashcards":[{"id":"ch-sugar-competition-check","front":"How did central factories change sugar production?","back":"A larger factory could process cane from several farms or estates, spreading the cost of machinery across more output."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-cuban-sugar', 'ch-theme-6', 'Cuba’s sugar expansion and British Caribbean competition', 'Cuban sugar output expanded in the nineteenth century as some British Caribbean producers struggled with prices and costs.', 19, true, '{"syllabus":{"theme":6,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Cuban sugar output expanded in the nineteenth century as some British Caribbean producers struggled with prices and costs.","objectives":["How did railways help Cuba’s sugar industry expand?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Cuba had extensive cultivable land, access to capital and a growing market. Rail transport, steam-powered machinery and larger mills moved and processed more cane. Slavery persisted in Cuba until 1886, then employers used different labour arrangements. The timing of modernisation, labour change and expansion varied across districts.","British Caribbean producers faced beet sugar competition and uneven access to capital. Responses included central factories, agricultural research, changes in cane varieties and efforts to secure markets. Small growers could face difficult bargaining with factories even as the industry became more efficient."]},{"title":"Work through an example","paragraphs":["Compare Cuba and one British territory by using the same factors: access to land, access to investment, transport and markets."]}],"summary":"They let estates move cane quickly over longer distances and carry processed sugar to ports, increasing the area a mill could serve.","check":{"question":"How did railways help Cuba’s sugar industry expand?","answer":"They let estates move cane quickly over longer distances and carry processed sugar to ports, increasing the area a mill could serve."},"flashcards":[{"id":"ch-cuban-sugar-check","front":"How did railways help Cuba’s sugar industry expand?","back":"They let estates move cane quickly over longer distances and carry processed sugar to ports, increasing the area a mill could serve."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-industry-and-tourism', 'ch-theme-6', 'Oil, bauxite, tourism and industrialisation', 'In the twentieth century, some territories built new sources of work and exports alongside agriculture.', 20, true, '{"syllabus":{"theme":6,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"In the twentieth century, some territories built new sources of work and exports alongside agriculture.","objectives":["Why can an economy grow while unemployment remains high?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Oil in Trinidad and bauxite in Jamaica and Guyana linked the region to international investment and export markets. Mining and petroleum brought revenue and employment, while capital-intensive extraction could create fewer jobs than expected and expose governments to world price changes.","Tourism expanded with air travel, marketing and investment in accommodation. Governments sought manufacturing jobs through policies such as tax concessions, industrial estates and import substitution. New industries changed who worked where and what skills were needed. Benefits depended on ownership, wages, links to local firms and spending retained in the country."]},{"title":"Work through an example","paragraphs":["Use tourism to distinguish revenue from retained income. Foreign ownership and imported supplies can send part of visitor spending abroad."]}],"summary":"An industry may produce valuable exports using expensive machinery and relatively few workers. Growth can also be concentrated in a few places or occupations.","check":{"question":"Why can an economy grow while unemployment remains high?","answer":"An industry may produce valuable exports using expensive machinery and relatively few workers. Growth can also be concentrated in a few places or occupations."},"flashcards":[{"id":"ch-industry-and-tourism-check","front":"Why can an economy grow while unemployment remains high?","back":"An industry may produce valuable exports using expensive machinery and relatively few workers. Growth can also be concentrated in a few places or occupations."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-us-expansion', 'ch-theme-7', 'From the Monroe Doctrine to the Panama Canal', 'The United States expanded its influence in the Caribbean through trade, diplomacy, strategic bases and military intervention.', 21, true, '{"syllabus":{"theme":7,"revisedTheme":5,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"The United States expanded its influence in the Caribbean through trade, diplomacy, strategic bases and military intervention.","objectives":["Why did the canal matter to both merchants and military planners?"],"sections":[{"title":"What happened and why it matters","paragraphs":["The Monroe Doctrine in 1823 opposed renewed European colonisation or intervention in the Americas. After the Spanish-American War in 1898, Puerto Rico came under US sovereignty and the US occupied Cuba. The Platt Amendment limited Cuban independence and provided grounds for US intervention.","The United States backed Panama’s separation from Colombia in 1903 and obtained Canal Zone rights. The canal opened in 1914, shortening voyages between the Atlantic and Pacific. Migrants from the Caribbean, including large numbers of Barbadians and Jamaicans, helped build and operate it, under a racially unequal labour system."]},{"title":"Work through an example","paragraphs":["A canal construction photograph can show infrastructure and workers. Use payroll and recruitment records to test claims about pay, housing or migration."]}],"summary":"Ships could move between the oceans faster, lowering shipping times and allowing naval forces to redeploy without rounding South America.","check":{"question":"Why did the canal matter to both merchants and military planners?","answer":"Ships could move between the oceans faster, lowering shipping times and allowing naval forces to redeploy without rounding South America."},"flashcards":[{"id":"ch-us-expansion-check","front":"Why did the canal matter to both merchants and military planners?","back":"Ships could move between the oceans faster, lowering shipping times and allowing naval forces to redeploy without rounding South America."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-occupations', 'ch-theme-7', 'US occupations and Caribbean responses', 'US officials justified intervention using stability, debt and strategic security. People in the affected territories also had their own aims and interpretations.', 22, true, '{"syllabus":{"theme":7,"revisedTheme":5,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"US officials justified intervention using stability, debt and strategic security. People in the affected territories also had their own aims and interpretations.","objectives":["Why distinguish an official justification from a historical explanation?"],"sections":[{"title":"What happened and why it matters","paragraphs":["The Roosevelt Corollary of 1904 asserted a US policing role in the region. Occupations included Haiti from 1915 to 1934 and the Dominican Republic from 1916 to 1924. US administrations influenced customs, finances, policing and infrastructure.","People opposed intervention for reasons including loss of sovereignty and coercion. In Haiti, Charlemagne Péralte was a leader of armed Caco resistance. Under the Good Neighbor policy of the 1930s, Washington shifted away from direct military occupation while economic and diplomatic influence continued."]},{"title":"Work through an example","paragraphs":["Compare an occupation’s roads or administrative changes with who controlled decisions and who bore the cost. These are different measures of its effects."]}],"summary":"A government’s stated aim is evidence of its position. An explanation also tests strategic, economic and local factors against other evidence.","check":{"question":"Why distinguish an official justification from a historical explanation?","answer":"A government’s stated aim is evidence of its position. An explanation also tests strategic, economic and local factors against other evidence."},"flashcards":[{"id":"ch-occupations-check","front":"Why distinguish an official justification from a historical explanation?","back":"A government’s stated aim is evidence of its position. An explanation also tests strategic, economic and local factors against other evidence."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-cold-war', 'ch-theme-7', 'The Cuban Revolution and the Cold War', 'After 1959, the Cuban Revolution changed regional politics as US–Soviet rivalry intensified.', 23, true, '{"syllabus":{"theme":7,"revisedTheme":5,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"After 1959, the Cuban Revolution changed regional politics as US–Soviet rivalry intensified.","objectives":["Why did US–Cuban relations worsen after 1959?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Fidel Castro’s movement overthrew Fulgencio Batista. Revolutionary reforms and nationalisation led to conflict with the United States. Cuba aligned with the Soviet Union. A US-backed exile invasion failed at the Bay of Pigs in 1961. The Cuban Missile Crisis in 1962 brought the superpowers close to nuclear war.","US policy mixed containment and aid. The Alliance for Progress sought development and influence. Caribbean governments made different choices about trade, diplomacy and security. In Grenada in 1983, an internal crisis and the killing of Maurice Bishop preceded an intervention by the United States and Caribbean partners."]},{"title":"Work through an example","paragraphs":["For Grenada, distinguish the local split and collapse of leadership from US regional objectives. Explain how they interacted."]}],"summary":"Nationalisation, geopolitical rivalry and US hostility to the revolutionary government reinforced one another as Cuba drew closer to the Soviet Union.","check":{"question":"Why did US–Cuban relations worsen after 1959?","answer":"Nationalisation, geopolitical rivalry and US hostility to the revolutionary government reinforced one another as Cuba drew closer to the Soviet Union."},"flashcards":[{"id":"ch-cold-war-check","front":"Why did US–Cuban relations worsen after 1959?","back":"Nationalisation, geopolitical rivalry and US hostility to the revolutionary government reinforced one another as Cuba drew closer to the Soviet Union."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-labour-protest', 'ch-theme-8', 'Labour protests and mass politics', 'The protests of the 1930s turned hardship into political pressure across the British Caribbean.', 24, true, '{"syllabus":{"theme":8,"revisedTheme":6,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"The protests of the 1930s turned hardship into political pressure across the British Caribbean.","objectives":["How did labour protest help expand political participation?"],"sections":[{"title":"What happened and why it matters","paragraphs":["The Great Depression worsened unemployment and low wages. Poor housing, insecure work and restricted voting added grievances. Trinidad’s oilfield unrest in 1937 and Jamaica’s strikes and demonstrations in 1938 grew from local labour conditions and spread beyond one workplace.","Workers, organisers and community networks forced colonial authorities to respond. The Moyne Commission investigated conditions. Trade unions gained influence and some leaders moved into party politics. In Jamaica, Alexander Bustamante and Norman Manley took different paths through labour organisation and party leadership."]},{"title":"Work through an example","paragraphs":["Give a long-term cause, a local trigger and a political consequence. For Jamaica, connect low wages and unemployment to strikes, then to organised labour’s increased influence."]}],"summary":"It organised workers, drew attention to social conditions and helped create unions and parties able to press for reform and voting rights.","check":{"question":"How did labour protest help expand political participation?","answer":"It organised workers, drew attention to social conditions and helped create unions and parties able to press for reform and voting rights."},"flashcards":[{"id":"ch-labour-protest-check","front":"How did labour protest help expand political participation?","back":"It organised workers, drew attention to social conditions and helped create unions and parties able to press for reform and voting rights."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-independence', 'ch-theme-8', 'From colonial government to independence', 'Independence involved changes in who could vote, who controlled ministers and who held ultimate constitutional authority.', 25, true, '{"syllabus":{"theme":8,"revisedTheme":6,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Independence involved changes in who could vote, who controlled ministers and who held ultimate constitutional authority.","objectives":["What is the difference between self-government and independence?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Crown Colony government concentrated power in governors and officials. Expanding the franchise made legislatures more representative. Adult suffrage in Jamaica in 1944 broadened electoral participation. Ministerial government and internal self-government gave elected leaders more responsibility before full independence.","Jamaica and Trinidad and Tobago became independent in 1962, and Barbados and Guyana in 1966. Constitutional paths differed, and some Caribbean territories remain linked to a metropolitan state. Independence gave governments formal sovereignty while they still faced trade dependence and social inequality."]},{"title":"Work through an example","paragraphs":["A territory can elect leaders before independence. Ask who controls foreign affairs, defence and constitutional change at each stage."]}],"summary":"Internal self-government transfers much domestic authority to local ministers. Independence gives the state sovereign control of its affairs.","check":{"question":"What is the difference between self-government and independence?","answer":"Internal self-government transfers much domestic authority to local ministers. Independence gives the state sovereign control of its affairs."},"flashcards":[{"id":"ch-independence-check","front":"What is the difference between self-government and independence?","back":"Internal self-government transfers much domestic authority to local ministers. Independence gives the state sovereign control of its affairs."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-regional-integration', 'ch-theme-8', 'Federation, CARIFTA and CARICOM', 'Caribbean governments tried different ways to cooperate while preserving local interests.', 26, true, '{"syllabus":{"theme":8,"revisedTheme":6,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Caribbean governments tried different ways to cooperate while preserving local interests.","objectives":["Why is 1973 significant in regional integration?"],"sections":[{"title":"What happened and why it matters","paragraphs":["The West Indies Federation operated from 1958 to 1962. It aimed to unite participating British territories politically. Disputes over financing, movement and the distribution of power weakened it. Jamaica voted to leave in 1961, and the Federation dissolved in 1962.","CARIFTA pursued trade cooperation. In 1973, the Treaty of Chaguaramas established the Caribbean Community and Common Market, covering economic integration, foreign policy coordination and functional cooperation. Regional cooperation could help small economies share services and bargain together while differing national priorities remained."]},{"title":"Work through an example","paragraphs":["Compare the Federation and CARICOM using their purpose and institutions. One sought political union; the other built cooperation among participating states."]}],"summary":"The Treaty of Chaguaramas created CARICOM, deepening earlier trade cooperation and extending it into other policy areas.","check":{"question":"Why is 1973 significant in regional integration?","answer":"The Treaty of Chaguaramas created CARICOM, deepening earlier trade cooperation and extending it into other policy areas."},"flashcards":[{"id":"ch-regional-integration-check","front":"Why is 1973 significant in regional integration?","back":"The Treaty of Chaguaramas created CARICOM, deepening earlier trade cooperation and extending it into other policy areas."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-constitutional-alternatives', 'ch-theme-8', 'Earlier unions and alternatives to independence', 'Caribbean political development included unsuccessful unions, independent states and territories that chose or retained another constitutional status.', 27, true, '{"syllabus":{"theme":8,"revisedTheme":6,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Caribbean political development included unsuccessful unions, independent states and territories that chose or retained another constitutional status.","objectives":["Why is constitutional status more precise than simply saying a territory is independent or colonial?"],"sections":[{"title":"What happened and why it matters","paragraphs":["British attempts to group colonies included Leeward Islands arrangements and nineteenth-century proposals in the Windward Islands. Objections over local powers, taxes and the distribution of benefits could prevent cooperation. Leaders such as Norman Manley and Grantley Adams later supported regional cooperation from different political positions.","Puerto Rico became a US commonwealth in 1952. Martinique and Guadeloupe became French overseas departments in 1946. Under the 1954 Charter, the Netherlands Antilles became a country within the Kingdom of the Netherlands. Compare these arrangements by local decision-making, citizenship and the authority retained by the metropolitan state at the time."]},{"title":"Work through an example","paragraphs":["For a comparison of Puerto Rico and Martinique, identify the outside state connected with each territory and ask how each arrangement represented the territory politically."]}],"summary":"Different arrangements distribute citizenship, elections, domestic policy and international authority in different ways.","check":{"question":"Why is constitutional status more precise than simply saying a territory is independent or colonial?","answer":"Different arrangements distribute citizenship, elections, domestic policy and international authority in different ways."},"flashcards":[{"id":"ch-constitutional-alternatives-check","front":"Why is constitutional status more precise than simply saying a territory is independent or colonial?","back":"Different arrangements distribute citizenship, elections, domestic policy and international authority in different ways."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-migration-and-community', 'ch-theme-9', 'Migration, cities and family life', 'Caribbean people moved for work, education and family reasons. Movement reshaped communities both at home and abroad.', 28, true, '{"syllabus":{"theme":9,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Caribbean people moved for work, education and family reasons. Movement reshaped communities both at home and abroad.","objectives":["How can migration change life in a village whose population falls?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Some moved within the region, to Panama for canal work or to towns from rural areas. Post-war migration to Britain, and later migration to North America, created new communities. Wages, transport, recruitment and immigration law shaped who moved and when.","Remittances helped households pay for food, housing and education. Separation could shift responsibilities to grandparents or other relatives. Urban migration supported new industries but could stretch housing and public services. Experiences varied by class, gender, age and destination."]},{"title":"Work through an example","paragraphs":["To explain a migration flow, pair a push factor such as limited rural jobs with a pull factor such as a recruitment offer or existing family network."]}],"summary":"Money and skills can circulate back, while caregiving, labour availability and household decisions change as relatives live in different places.","check":{"question":"How can migration change life in a village whose population falls?","answer":"Money and skills can circulate back, while caregiving, labour availability and household decisions change as relatives live in different places."},"flashcards":[{"id":"ch-migration-and-community-check","front":"How can migration change life in a village whose population falls?","back":"Money and skills can circulate back, while caregiving, labour availability and household decisions change as relatives live in different places."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-identity-and-reform', 'ch-theme-9', 'Culture, education and social change', 'Culture is evidence of what communities preserved, adapted and created under changing conditions.', 29, true, '{"syllabus":{"theme":9,"revisedTheme":6,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Culture is evidence of what communities preserved, adapted and created under changing conditions.","objectives":["What makes a cultural practice historical evidence?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Carnival traditions in Trinidad, Rastafari in Jamaica and Indian religious festivals in Guyana and Trinidad illustrate different forms of cultural expression. These practices changed over time and were shaped by religion, migration, social conflict and community organisation.","Schools, newspapers, religious bodies, unions and organisations widened public debate. Marcus Garvey’s UNIA linked racial pride, self-reliance and a transnational Black identity. Education expanded opportunities, while differences in school access and employment could reproduce inequalities."]},{"title":"Work through an example","paragraphs":["Use a named practice and explain who created or maintained it, how it changed, and why it mattered. Avoid treating the region as if every territory shared the same history."]}],"summary":"It can show continuity, adaptation and public debate. Its date, community and context help establish what it can tell us.","check":{"question":"What makes a cultural practice historical evidence?","answer":"It can show continuity, adaptation and public debate. Its date, community and context help establish what it can tell us."},"flashcards":[{"id":"ch-identity-and-reform-check","front":"What makes a cultural practice historical evidence?","back":"It can show continuity, adaptation and public debate. Its date, community and context help establish what it can tell us."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-living-conditions', 'ch-theme-9', 'Living conditions and organising for change', 'Between 1900 and 1935, colonial prosperity and everyday living conditions could tell different stories.', 30, true, '{"syllabus":{"theme":9,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Between 1900 and 1935, colonial prosperity and everyday living conditions could tell different stories.","objectives":["How can a historian test claims about the cost of living?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Low wages and irregular work left families exposed to rising prices. Crowded housing, limited sanitation and inadequate medical care affected health. Port and railway transport connected export areas, and roads, newspapers and radio changed access to work, news and recreation.","Unions pressed for wages and working conditions. Women’s organisations organised around welfare, education, legal reform and political participation. Governments and religious bodies provided some services, but their access and quality varied. Compare changes in policy with actual changes in people’s lives."]},{"title":"Work through an example","paragraphs":["Suppose wages increased but food and rent rose faster. Compare the prices of everyday goods with the wage to explain why a pay increase might not improve living standards."]}],"summary":"Compare wages and household expenses over time, using price lists, budgets, labour records or testimony from the same place.","check":{"question":"How can a historian test claims about the cost of living?","answer":"Compare wages and household expenses over time, using price lists, budgets, labour records or testimony from the same place."},"flashcards":[{"id":"ch-living-conditions-check","front":"How can a historian test claims about the cost of living?","back":"Compare wages and household expenses over time, using price lists, budgets, labour records or testimony from the same place."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-religious-communities', 'ch-theme-9', 'Religious communities and social life', 'Religion helped communities preserve beliefs, organise mutual support and respond to exclusion or change.', 31, true, '{"syllabus":{"theme":9,"revisedTheme":4,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Religion helped communities preserve beliefs, organise mutual support and respond to exclusion or change.","objectives":["Why should a comparison name the territory and period?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Established and evangelical Christian churches ran schools and missions. Migrants from India founded Hindu and Muslim institutions, maintained worship and built networks of support. African-influenced traditions such as Orisha in Trinidad, Kumina in Jamaica and Revival traditions developed through adaptation and community practice.","Rastafari emerged in Jamaica in the 1930s amid colonial racial inequality, and developed distinctive religious and political ideas tied to Africa and liberation. In different territories, religious membership could provide solidarity or leadership opportunities while members also faced discrimination or restrictions."]},{"title":"Work through an example","paragraphs":["Compare a recognised church’s access to schools and public authority with a community whose worship authorities restricted. Explain how status shaped the opportunities members had."]}],"summary":"The same tradition can be treated differently by local authorities and communities, and its practices and public standing change over time.","check":{"question":"Why should a comparison name the territory and period?","answer":"The same tradition can be treated differently by local authorities and communities, and its practices and public standing change over time."},"flashcards":[{"id":"ch-religious-communities-check","front":"Why should a comparison name the territory and period?","back":"The same tradition can be treated differently by local authorities and communities, and its practices and public standing change over time."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-source-analysis', 'ch-skills', 'Read a historical source', 'Start by asking who made the source, when, for whom and why. Use those answers to work out which claims the source can support.', 32, true, '{"syllabus":{"theme":null,"revisedTheme":null,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Start by asking who made the source, when, for whom and why. Use those answers to work out which claims the source can support.","objectives":["How do you explain a limitation without dismissing the whole source?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Describe what is actually present before drawing an inference. A payroll can record rates and job categories. It may leave out unpaid work, threats or people whose names were never recorded.","To assess usefulness, name the question you are investigating. A planter’s letter can be useful evidence of what planters told officials and weak evidence of how workers felt. Compare it with a worker’s testimony or a record created for a different purpose.","For a photograph or engraving, look at framing, caption and date. A picture can show equipment, clothing and where people stood. It can also stage a scene or omit conflict."]},{"title":"Work through an example","paragraphs":["A newspaper reports that a strike ended after workers accepted a wage offer. Look for the date, which workers the reporter interviewed and whether union or payroll records support that account."]}],"summary":"Name the detail the source supports and a specific question it cannot answer. Then identify another source that could help.","check":{"question":"How do you explain a limitation without dismissing the whole source?","answer":"Name the detail the source supports and a specific question it cannot answer. Then identify another source that could help."},"flashcards":[{"id":"ch-source-analysis-check","front":"How do you explain a limitation without dismissing the whole source?","back":"Name the detail the source supports and a specific question it cannot answer. Then identify another source that could help."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-essay-writing', 'ch-skills', 'Plan an answer that earns marks', 'Read the command word, circle the place and dates, then check how many points the question requests.', 33, true, '{"syllabus":{"theme":null,"revisedTheme":null,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Read the command word, circle the place and dates, then check how many points the question requests.","objectives":["What should follow a specific example in an explanation?"],"sections":[{"title":"What happened and why it matters","paragraphs":["State or identify asks for the fact. Describe asks what happened or what something was like. Explain asks how or why. Compare uses the same basis for each example. Discuss develops and weighs relevant arguments.","Make one point per paragraph. Give evidence by naming a place, group, policy or event. Follow it with a sentence linking the evidence to the question. If the question asks for the most important cause, explain what makes it more important than another cause.","For a three-question, two-hour paper, about forty minutes per answer is a starting point. Read the instructions before budgeting time. A short answer needs direct, labelled parts. An extended response needs a clear position, supported paragraphs and a conclusion that answers the question."]},{"title":"Work through an example","paragraphs":["Turn ‘low wages caused protests’ into an explanation: low wages made basic goods difficult to afford, so a wage demand could mobilise workers across several workplaces."]}],"summary":"A sentence explaining how or why the example supports the point you are making.","check":{"question":"What should follow a specific example in an explanation?","answer":"A sentence explaining how or why the example supports the point you are making."},"flashcards":[{"id":"ch-essay-writing-check","front":"What should follow a specific example in an explanation?","back":"A sentence explaining how or why the example supports the point you are making."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values ('caribbean-history', 'ch-sba', 'ch-skills', 'Build a manageable SBA investigation', 'Choose a historical question narrow enough to investigate with evidence you can actually find.', 34, true, '{"syllabus":{"theme":null,"revisedTheme":null,"sourceUrl":"https://www.cxc.org/syllabus-downloads/"},"lesson":{"introduction":"Choose a historical question narrow enough to investigate with evidence you can actually find.","objectives":["How can you tell if your investigation is too broad?"],"sections":[{"title":"What happened and why it matters","paragraphs":["Specify the place, period and event or change. ‘Why did workers protest in Jamaica in 1938?’ gives a clearer route into archives than ‘What is labour history?’","Keep a source log with creator, title, date, page or stable link, notes, and how each source helps. Distinguish quotations, paraphrases and your own interpretations. Compare at least two perspectives where the material permits it.","Draft your own argument. Check the assessment guidance for your sitting, especially if taking the alternative Paper 032. Use feedback to improve how you cite evidence and explain the limits of your conclusions."]},{"title":"Work through an example","paragraphs":["For a question on post-emancipation land ownership, compare a purchase record with evidence of settlement, work or community institutions."]}],"summary":"If you cannot identify a specific place, period and question, or your sources cover many unrelated issues, narrow the scope before collecting more material.","check":{"question":"How can you tell if your investigation is too broad?","answer":"If you cannot identify a specific place, period and question, or your sources cover many unrelated issues, narrow the scope before collecting more material."},"flashcards":[{"id":"ch-sba-check","front":"How can you tell if your investigation is too broad?","back":"If you cannot identify a specific place, period and question, or your sources cover many unrelated issues, narrow the scope before collecting more material."}]}}'::jsonb)
  on conflict (subject_id, topic_id) do update set section_id = excluded.section_id, title = excluded.title, description = excluded.description, sort_order = excluded.sort_order, metadata = excluded.metadata, updated_at = now();
